CREATE TABLE finance_reconciliation_allocations(id text PRIMARY KEY,company_id text NOT NULL,row_id text NOT NULL,expense_id text NOT NULL,expected_row_version bigint NOT NULL,expected_expense_version bigint NOT NULL,paid_economic_fingerprint text NOT NULL,request_hash text NOT NULL,amount_minor bigint NOT NULL CHECK(amount_minor BETWEEN 1 AND 1000000000000),actor_id text NOT NULL,reason text NOT NULL,active boolean NOT NULL,version bigint NOT NULL,created_at timestamptz NOT NULL,reversed_at timestamptz);
CREATE UNIQUE INDEX finance_allocation_active_row ON finance_reconciliation_allocations(company_id,row_id) WHERE active;
CREATE UNIQUE INDEX finance_allocation_active_expense ON finance_reconciliation_allocations(company_id,expense_id) WHERE active;
CREATE TABLE finance_reconciliation_decisions(id text PRIMARY KEY,company_id text NOT NULL,row_id text NOT NULL,allocation_id text NOT NULL DEFAULT '',suggestion_basis text NOT NULL DEFAULT '',actor_id text NOT NULL,reason text NOT NULL,action text NOT NULL CHECK(action IN ('match','unmatch','dismiss')),retry_key text NOT NULL,reviewed_version bigint NOT NULL,created_at timestamptz NOT NULL);
